on conflict (id) do nothing;

insert into court_surfaces (court_id, code, name, capacity, surface, size, image_url, sort_order)
select id, '01', name || ' 01', 'Sân tiêu chuẩn', 'Mặt sân tổng hợp', 'Theo môn thi đấu', 'https://images.unsplash.com/photo-1526232761682-d26e03ac148e?auto=format&fit=crop&w=500&q=80', 1
from courts where id between 'c0021' and 'c0040'
  and not exists (select 1 from court_surfaces cs where cs.court_id = courts.id and cs.code = '01');

insert into court_images (court_id, image_url, sort_order)
select id, 'https://images.unsplash.com/photo-1526232761682-d26e03ac148e?auto=format&fit=crop&w=1200&q=80', 1 from courts where id between 'c0021' and 'c0040'
  and not exists (select 1 from court_images ci where ci.court_id = courts.id and ci.sort_order = 1)
union all
select id, 'https://images.unsplash.com/photo-1579952363873-27f3bade9f55?auto=format&fit=crop&w=1200&q=80', 2 from courts where id between 'c0021' and 'c0040'
  and not exists (select 1 from court_images ci where ci.court_id = courts.id and ci.sort_order = 2);

insert into court_amenities (court_id, name)
select id, unnest(array['Gửi xe', 'Đèn chiếu sáng', 'Phòng thay đồ', 'Nước uống', 'Nhà vệ sinh', 'Khu nghỉ chờ']) from courts where id between 'c0021' and 'c0040'
  and not exists (select 1 from court_amenities ca where ca.court_id = courts.id);

insert into court_prices (court_id, day_type, start_time, end_time, price, note)
select id, 'WEEKDAY'::day_type, '06:00'::time, '17:00'::time, 130000, 'Giờ thấp điểm' from courts where id between 'c0021' and 'c0040'
  and not exists (select 1 from court_prices cp where cp.court_id = courts.id)
union all
select id, 'WEEKDAY'::day_type, '17:00'::time, '23:00'::time, 210000, 'Giờ cao điểm' from courts where id between 'c0021' and 'c0040'
  and not exists (select 1 from court_prices cp where cp.court_id = courts.id)
union all
select id, 'WEEKEND'::day_type, '06:00'::time, '23:00'::time, 240000, 'Cuối tuần' from courts where id between 'c0021' and 'c0040'
  and not exists (select 1 from court_prices cp where cp.court_id = courts.id);

insert into court_services (court_id, name, description, price)
select id, 'Nước suối', 'Chai 500ml', 10000 from courts where id between 'c0021' and 'c0040'
  and not exists (select 1 from court_services cs where cs.court_id = courts.id)
union all
select id, 'Thuê dụng cụ', 'Dụng cụ cơ bản theo môn', 50000 from courts where id between 'c0021' and 'c0040'
  and not exists (select 1 from court_services cs where cs.court_id = courts.id)
union all
select id, 'Trọng tài', 'Hỗ trợ điều hành trận đấu', 150000 from courts where id between 'c0021' and 'c0040'
  and not exists (select 1 from court_services cs where cs.court_id = courts.id);
